import {icon} from './icons.mjs';
import {rankBadge} from './rank-art.mjs';
import {recordMatch,LEVEL_NAMES} from './history.mjs';
import {tutorialAdvice} from './tutorial.mjs';
import {animateShots,toggleSound,soundEnabled} from './effects.mjs';
import {accounts} from './accounts.mjs';
import {cleanNick,calculateRank,rankMark} from './profile.mjs';
import {boostVisuals,lightning} from './boost-visuals.mjs';
import {PRICES,BASE,QUESTS,STORAGE_KEY,freshProgress,validateProgress,purchase,botShopping,settle,mergeOnlineEarnings,redeemPromo,instantWinsLeft,useInstantWin} from './economy.mjs';
import {DIRS,TYPES,BOOSTERS,DIRECTED,createGame,action,shot,boosts,botAction} from './engine.mjs';
let accountManager=null,accountStorage=localStorage;try{accountManager=accounts(localStorage);accountStorage=accountManager.storage;}catch{}
const app=document.querySelector('#app');const dirs=document.querySelector('#directions');const rules=document.querySelector('#rules');
let g=null,mode='local',level=2,fieldHeight=28,fieldWidth=20,selected=null,chosenCell=null,busy=false,zoom=false,notice='',epoch=0,screen='splash';
let progress,firstVisit=false,storageError='',storageReady=true,matchId='',actionId=0;
try{const raw=accountStorage.getItem(STORAGE_KEY);progress=raw?validateProgress(JSON.parse(raw)):freshProgress();if(!raw){accountStorage.setItem(STORAGE_KEY,JSON.stringify(progress));firstVisit=true;}}catch{progress=freshProgress();storageReady=false;storageError='Не удалось открыть сохранение. Баксы и покупки сейчас не сохраняются. Проверь доступ браузера к данным сайта.';}
function saveProgress(){if(!storageReady)return false;try{accountStorage.setItem(STORAGE_KEY,JSON.stringify(progress));storageError='';return true;}catch{storageError='Не удалось сохранить прогресс. Не закрывай страницу: попробуй ещё раз после освобождения памяти браузера.';return false;}}
function balance(){return `<div class="wallet" aria-label="Баланс: ${progress.human.balance} баксов"><span aria-hidden="true">$</span> ${progress.human.balance} <small>баксов</small></div>`;}
function economyPage(which,message=''){
 screen=which;epoch++;g=null;busy=false;selected=null;
 let body='';if(which==='shop')body=`<h1>Рынок</h1><p class="economy-intro">Открой символ один раз — играй им в каждой партии.</p><div class="shop-grid">${Object.entries(PRICES).map(([t,price])=>{const owned=progress.human.unlocked.includes(t);return `<article class="shop-card"><div class="shop-symbol">${icon(t)}</div><h2>${TYPES[t].name}</h2><p>${descriptions[t]}</p><button class="${owned?'owned':'primary'}" data-buy="${t}" ${owned||progress.human.balance<price?'disabled':''}>${owned?'✓ Открыто':`Открыть · ${price} баксов`}</button>${!owned&&progress.human.balance<price?`<small>Нужно ещё ${price-progress.human.balance}</small>`:''}</article>`;}).join('')}</div><p class="hint">Сразу доступны: стрелочка, смайлик, точка и удаление. Запас купленного символа обновляется в каждой партии.</p>`;
 else body=`<h1>Задания</h1><p class="economy-intro">Выполняй сколько угодно раз. Баксы начисляются автоматически.</p><div class="quest-list">${QUESTS.map(q=>`<article class="quest-card"><div class="quest-reward">+${q.reward}<small>баксов</small></div><div><h2>${q.title}</h2><p>${q.text}</p>${q.id==='streak'?`<div class="streak-dots" aria-label="${progress.human.streak} из 5 побед">${Array.from({length:5},(_,i)=>`<span class="${i<progress.human.streak?'filled':''}">${i+1}</span>`).join('')}</div><p class="hint">Только против бота · серия ${progress.human.streak}/5</p>`:''}<small>Выполнено: ${progress.human.counts[q.id]??0} · без ограничений</small></div></article>`).join('')}</div><div class="economy-note">Вдвоём на одном устройстве вы зарабатываете в общий кошелёк. У бота отдельный кошелёк: ${progress.bot.balance} баксов. Он открывает себе символы перед новой партией.</div>`;
 app.innerHTML=`<section class="economy-page"><header class="topbar">${brand()}${balance()}</header><nav class="economy-nav"><button class="quiet" data-menu="home">← На главную</button><button class="quiet" data-menu="${which==='shop'?'quests':'shop'}">${which==='shop'?'Задания':'Рынок'}</button></nav>${message?`<p class="notice" role="status">${message}</p>`:''}${storageError?`<p class="notice" role="alert">${storageError}</p>`:''}${body}</section>`;
 bindCommon();app.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const before=structuredClone(progress);try{purchase(progress,b.dataset.buy);if(!saveProgress()){progress=before;economyPage('shop','Покупка не сохранена, баксы не списаны.');return;}economyPage('shop',`${TYPES[b.dataset.buy].name}: теперь доступен в каждой партии!`);}catch(e){economyPage('shop',e.message);}});
}
let teleportSource=null,trialActive=false,trialDamage=0,trialRecorded=false,trialStartedAt=null,trialElapsed=0,onlineMatch=null,onlineRevision=-1,onlineBusy=false,onlineCount=null,searchSince=0,onlineError='',onlineRematching=false,onlineClockOffset=0;
let session=null,sessionPromise=null;try{session=JSON.parse(accountStorage.getItem('symbols-session')||'null');}catch{}
const nickDialog=document.createElement('dialog');nickDialog.id='nick-dialog';document.body.append(nickDialog);
const opponentDialog=document.createElement('dialog');opponentDialog.id='opponent-dialog';document.body.append(opponentDialog);
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function presence(){return `<span class="presence-pill" data-presence>В игре: ${onlineCount===null?'…':onlineCount}</span>`;}
function nickControls(){return `<div class="profile-line"><button class="nick-button" data-nick>${escapeHtml(progress.nick||'Выбрать ник')}</button><button class="quiet" data-profile>Профиль</button><span class="corner-rank rank-${progress.rank?.index??'none'}">${rankBadge(progress.rank)}</span></div>${presence()}`;}

async function api(route,body={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch('/api/'+route,{method:'POST',headers:{'Content-Type':'application/json',...(session?{Authorization:'Bearer '+session.token}:{})},body:JSON.stringify(body),signal:controller.signal});const data=await r.json();if(!r.ok)throw Error(data.error||'Ошибка соединения');return data;}catch(e){throw Error(e.name==='AbortError'?'Сервер не ответил. Проверь интернет и повтори.':e.message);}finally{clearTimeout(timer);}}
async function ensureSession(){if(!progress.nick){showNick();throw Error('Сначала придумай ник');}if(session)return session;if(!sessionPromise)sessionPromise=(async()=>{const data=await api('register',{nick:progress.nick,progress});session={id:data.id,token:data.token};accountStorage.setItem('symbols-session',JSON.stringify(session));return session;})().finally(()=>{sessionPromise=null;});return sessionPromise;}

function showNick(opponent=null){if(opponent){nickDialog.innerHTML=`<h2>${escapeHtml(opponent.nick)}</h2><p class="rank-mark rank-${opponent.rank?.index??'none'}">${rankBadge(opponent.rank,'large')}</p><button class="primary" data-close>Закрыть</button>`;nickDialog.querySelector('[data-close]').onclick=()=>nickDialog.close();}else{nickDialog.innerHTML=`<h2>Как ты себя назовёшь?</h2><p class="rank-mark rank-${progress.rank?.index??'none'}">${rankBadge(progress.rank)}</p><label for="nick-input">Придумай ник</label><input id="nick-input" maxlength="20" autocomplete="off" value="${escapeHtml(progress.nick||'')}" placeholder="Например, ЛунныйТанк"><p class="hint">Не указывай своё настоящее имя. Без мата.</p><p id="nick-error" role="alert"></p><div class="dialog-actions"><button class="primary" data-save>Изменить</button><button class="quiet" data-close>Отмена</button></div>`;nickDialog.querySelector('[data-close]').onclick=()=>nickDialog.close();nickDialog.querySelector('[data-save]').onclick=async()=>{try{const nick=cleanNick(nickDialog.querySelector('input').value);if(session)await api('nickname',{nick});progress.nick=nick;saveProgress();nickDialog.close();document.querySelectorAll('[data-nick]').forEach(b=>b.textContent=nick);maybeStartTutorial();await ensureSession();}catch(e){nickDialog.querySelector('#nick-error').textContent=e.message;}};}if(!nickDialog.open)nickDialog.showModal();}
function showOpponent(player){opponentDialog.innerHTML=`<h2>Твой соперник: ${escapeHtml(player.nick)}</h2><button class="quiet rank-mark rank-${player.rank?.index??'none'}" data-rank>${rankBadge(player.rank)}</button><p>Доступные символы</p><div class="opponent-pieces">${player.unlocked.filter(t=>TYPES[t]).map(t=>`<div>${icon(t)}<span>${TYPES[t].name}</span></div>`).join('')}</div><button class="primary" data-ready>Играть</button>`;opponentDialog.querySelector('[data-ready]').onclick=()=>{opponentDialog.close();if(trialActive&&trialStartedAt===null)trialStartedAt=performance.now();};opponentDialog.querySelector('[data-rank]').onclick=()=>showNick(player);if(!opponentDialog.open)opponentDialog.showModal();}
function showOnlineOptions(message=''){screen='online-options';g=null;mode='online';app.innerHTML=`<section class="menu difficulty"><header class="topbar">${brand()}${balance()}</header><h1>Онлайн-дуэль</h1><p>Один на один</p>${message?`<p class="notice">${escapeHtml(message)}</p>`:''}<div class="menu-actions"><button class="choice" id="create-room">Создать комнату</button><label for="room-code">Код комнаты</label><div class="join-room"><input id="room-code" maxlength="6" placeholder="ABC123" autocomplete="off"><button class="primary" id="join-room">Войти</button></div><button class="choice" id="random-search">Со случайным соперником</button><button class="quiet" data-menu="modes">Назад</button></div></section>`;bindCommon();app.querySelector('#create-room').onclick=()=>{mode='room-create';menu('size')};app.querySelector('#join-room').onclick=()=>beginOnline('join',{code:app.querySelector('#room-code').value});app.querySelector('#random-search').onclick=()=>beginOnline('queue');}
async function beginOnline(route,body={}){if(onlineBusy)return;onlineBusy=true;try{await ensureSession();const synced=await api('sync',{nick:progress.nick,progress});progress=synced.profile;saveProgress();mode='online';searchSince=Date.now();const data=await api(route,body);onlineBusy=false;await applyOnline(data);}catch(e){onlineBusy=false;showOnlineOptions(e.message);}}
function onlineWaiting(message=''){if(!onlineMatch)return;const m=onlineMatch,s=m.state;screen='online-wait';let content='';if(m.status==='waiting')content=`<h1>Ищем подходящую игру</h1>${m.code?`<p>Отправь другу код комнаты</p><div class="room-code">${m.code}</div><p>Поле ${s.size.join(' × ')}</p>`:'<p>Ждём другого игрока для дуэли.</p>'}<p class="search-clock" data-search-clock>0 с</p>`;else content=`<h1>${s.round?'Размеры не совпали':'Игра найдена'}</h1><p>${s.round?'Попробуйте выбрать одинаковый размер ещё раз.':'Какое поле хотите?'}</p><p>${escapeHtml(s.players[1-m.seat]?.nick)}</p><div class="menu-actions"><button class="choice" data-online-size="large">28 × 20</button><button class="choice" data-online-size="small">10 × 14</button></div><p>${s.choices[m.seat]?'Твой выбор: '+s.choices[m.seat].join(' × ')+'. Ждём соперника.':''}</p>`;app.innerHTML=`<section class="menu difficulty"><header class="topbar">${brand()}${balance()}</header>${content}${message?`<p class="notice">${escapeHtml(message)}</p>`:''}<button class="quiet" id="cancel-online">Отменить поиск</button></section>`;bindCommon();app.querySelector('#cancel-online').onclick=leaveOnline;app.querySelectorAll('[data-online-size]').forEach(b=>b.onclick=async()=>{try{await applyOnline(await api('size',{size:b.dataset.onlineSize==='small'?[10,14]:[28,20]}));}catch(e){onlineWaiting(e.message);}});}
async function leaveOnline(){try{await api('leave');onlineMatch=null;onlineRevision=-1;busy=false;opponentDialog.close();menu('modes');}catch(e){onlineError=e.message;updateOnlineBadges();}}
async function applyOnline(data){if(data.serverNow)onlineClockOffset=data.serverNow-Date.now();onlineCount=data.online??onlineCount;updateOnlineBadges();if(!data.match)return;const m=data.match;if(onlineMatch?.id===m.id&&m.revision<onlineRevision)return;if(onlineMatch?.id===m.id&&onlineRevision===m.revision){onlineMatch=m;updateOnlineBadges();return;}const newMatch=onlineMatch?.id!==m.id;onlineMatch=m;onlineRevision=m.revision;mode='online';if(data.profile){progress=data.profile;saveProgress();}if(m.status==='waiting'||m.status==='negotiate'){g=null;onlineWaiting();return;}if(m.state.rematch){if(!onlineRematching){onlineRematching=true;try{await api('leave');onlineMatch=null;onlineRevision=-1;searchSince=Date.now();await applyOnline(await api('queue'));}finally{onlineRematching=false;}}return;}
 const priorPhase=screen;g=m.state.g;if(!g)return;fieldHeight=g.height;fieldWidth=g.width;screen='game';selected=null;teleportSource=null;busy=false;notice=m.state.lastResult?.free&&g.pending.some(v=>v.player!==m.seat)?'Своя фигура удалена. Вражеский выстрел остаётся: он полетит после твоего хода.':m.state.lastResult?.cancelled?'Ответная атака отменена. Выбери другой ход.':'';render();updateOnlineBadges();if(m.status==='warmup'&&(newMatch||priorPhase!=='game'))showOpponent(m.state.players[1-m.seat]);if(m.status==='play')opponentDialog.close();
 if(m.state.events?.length){busy=true;await animateShots(app,m.state.events,()=>onlineMatch?.id===m.id);busy=false;}
 if(m.status==='done'){opponentDialog.close();overlay(g.winner===m.seat?'Ты победил!':'Победил соперник',m.state.reason||'Дуэль завершена.','В онлайн-меню',async()=>{await api('leave');onlineMatch=null;onlineRevision=-1;showOnlineOptions();});}
}
async function performOnline(a){if(onlineBusy||busy)return;onlineBusy=true;try{await applyOnline(await api('action',{action:a,revision:onlineMatch.revision}));}catch(e){notice=e.message;render();}finally{onlineBusy=false;}}
function updateOnlineBadges(){document.querySelectorAll('[data-presence]').forEach(e=>e.textContent='В игре: '+(onlineCount??'…'));const clock=document.querySelector('[data-search-clock]');if(clock)clock.textContent=Math.floor((Date.now()-searchSince)/1000)+' с';const banner=document.querySelector('#online-banner');if(banner&&onlineMatch){const m=onlineMatch;banner.textContent=onlineError|| (m.reconnect!==null?`Соперник потерял связь. На возвращение: ${m.reconnect} с` : m.status==='warmup'?`Разминка · ${Math.max(0,Math.ceil((m.state.warmupEnd-Date.now()-onlineClockOffset)/1000))} с · без наград`:m.status==='play'?'Онлайн-дуэль':'Дуэль завершена');}}
setInterval(async()=>{if(!progress.nick)return;if(onlineBusy||busy)return;try{await ensureSession();const data=await api('poll');onlineError='';onlineCount=data.online;if(data.match&&data.match.status!=='done'||mode==='online'&&onlineMatch&&data.match)await applyOnline(data);else{if(data.profile){mergeOnlineEarnings(progress,data.profile);saveProgress();}updateOnlineBadges();}}catch(e){onlineError='Нет связи с сервером. Переподключаемся…';onlineCount=null;updateOnlineBadges();}},2500);
setInterval(updateOnlineBadges,1000);
function beginTrial(){trialActive=true;progress.trial??={results:[],size:null};mode='trial';if(progress.trial.size){[fieldHeight,fieldWidth]=progress.trial.size;level=progress.trial.results.length;start('bot');}else menu('size');}
function recordTrial(result){if(!trialActive||trialRecorded)return;trialDamage+=result.events.reduce((n,e)=>n+(e.hits?.[0]||0),0);if(g.winner===null)return;trialRecorded=true;progress.trial.results.push({won:g.winner===0,damage:trialDamage,elapsedMs:trialStartedAt===null?Infinity:performance.now()-trialStartedAt});if(progress.trial.results.length===5){progress.rank=calculateRank(progress.trial.results,progress.rank);progress.trial=null;}saveProgress();}
function trialFinish(){const finished=!progress.trial;overlay(finished?'Твоё звание: '+progress.rank.name:`Партия ${progress.trial.results.length} из 5 завершена`,finished?`${rankMark(progress.rank)}. Побед: ${progress.rank.wins}/5, получено урона: ${progress.rank.damage}.`:'Следующая партия — следующий уровень сложности.',finished?'В меню':'Следующая партия',()=>{if(finished){trialActive=false;menu();}else{level=progress.trial.results.length;start('bot');}});}
const arrows=['↑','↗','→','↘','↓','↙','←','↖'];
const descriptions={sword:'250 урона. Пробивает до двух кругов и электрический щит. Каждый уничтоженный блок или усилитель отнимает 50 урона. Обратная связь отражает меч. Запас: 2.',electricity:'Красный щит X2. Останавливает стрелочку, лазер и танк даже с усилителями. Меч пробивает щит, теряя 50 урона. Запас: 5.',arrow:'Один выстрел: 20 урона. С одной точкой — 50, после смайлика — 20. С пятью точками пробивает круг и наносит 70. Треугольник всегда отражает стрелочку.',smile:'Останавливает слабую пулю. Если выдержал удар, остаётся на поле.',point:'Обычная пуля уничтожает точку и исчезает. Сила усиления: 1. Королю добавляет 10 жизней, пока усиление действует. Выбери одно из восьми направлений.',laser:'100 урона. С одним усилением пробивает круг, с десятью — треугольник, после которого наносит 50 урона. Запас: 15.',circle:'Сильный блок. Танк пробивает обычный круг без усиления, лазер — с одним усилением, стрелочка — с пятью. Меч тоже пробивает круг. Запас: 10.',feedback:'Отражает пулю назад по тому же пути без дополнительного хода. Остаётся на поле. Пуля отражается только один раз. Лазер пробивает с 10 усилениями, танк — с 1. Запас: 5.',tank:'200 урона даже после пробития. Пробивает усиленный смайлик; обычный круг — без усиления, треугольник — с одним усилением. Электричество не пробивает. Если уничтожил усилитель, пуля летит дальше. Стреляет один раз и исчезает. Запас: 5.',inspect:'Уничтожается лазером или стрелочкой с 3 усилениями; пуля исчезает. Сила трёх точек. Королю добавляет 30 жизней, пока усиление действует. Запас: 20.',powerful:'Уничтожается танком, лазером с 2 усилениями или стрелочкой с 5. Пуля танка после уничтожения летит дальше, остальные исчезают. Сила шести точек, или двух «Осмотров». Королю добавляет 60 жизней, пока усиление действует. Запас: 15.',angry:'Два действия подряд. Можно применить 5 раз за партию.',teleport:'Перенеси свой символ в свободную клетку и обнови его. Можно выбрать новое направление. Тратит ход, 10 раз за партию. Цена: 100 баксов.',erase:'Бесплатно удаляет свой символ во время своего хода. После удаления ход продолжается. Короля удалить нельзя.'};

const name=p=>mode==='online'?escapeHtml(onlineMatch?.state.players[p]?.nick||'Соперник'):mode==='bot'&&p===1?'Бот':p===0?escapeHtml(progress.nick||'Игрок 1'):'Игрок 2';
function brand(){return '<div class="profile-controls">'+nickControls()+'</div><div class="brand"><span class="brand-mark">↗</span>Символы</div>';}

function menu(which='home'){tutorialActive=false;if(which==='online'){showOnlineOptions();return;}if(['shop','quests'].includes(which)){economyPage(which);return;}screen=which;epoch++;g=null;busy=false;selected=null;let content='';if(which==='home')content='<div class="menu-art"><div class="symbol-tile">'+icon('arrow',1)+'</div><div class="symbol-tile">'+icon('king')+'</div><div class="symbol-tile">'+icon('smile')+'</div></div><h1>Символы</h1><p class="game-description">Символы — бесплатная пошаговая игра: защищай короля, ставь блоки и усилители. Играй с ботом, вдвоём на одном устройстве или в онлайн-дуэли.</p><div class="home-side-actions"><button class="choice" data-menu="quests">Задания</button><button class="choice" data-menu="shop">Рынок</button></div>'+``+'<div class="menu-actions"><button class="primary" data-menu="modes">Играть</button><button class="choice" data-account>Аккаунт</button><button class="choice promo-button" data-promo>Промокоды <span>＋</span></button><button class="quiet" data-rules>Правила игры</button></div>';else if(which==='modes')content='<div class="menu-art"><div class="symbol-tile">'+icon('king')+'</div><div class="symbol-tile">'+icon('king')+'</div></div><h1>С кем играем?</h1><div class="menu-actions"><button class="choice" data-mode="local">Играть на одном устройстве <span>↗</span></button><button class="choice" data-mode="bot">Играть с ботом <span>↗</span></button><button class="choice" data-mode="online">Играть онлайн <span>↗</span></button><button class="choice" data-trial>'+(progress.rank?'Улучшить звание':'Получить звание')+'</button><button class="quiet" data-menu="home">Назад</button></div>';else if(which==='size')content='<h1>Как будем играть?</h1><p>Выбери размер поля: высота × ширина.</p><div class="menu-actions"><button class="choice" data-size="large">28 × 20 клеток <span>↗</span></button><button class="choice" data-size="small">10 × 14 клеток <span>↗</span></button><button class="quiet" data-menu="modes">Назад</button></div>';else content='<h1>Выбери сложность</h1><p>От первых шагов до серьёзного вызова.</p><div class="menu-actions">'+['Очень лёгкий','Лёгкий','Средний','Сложный','Безумно сложный'].map((v,i)=>`<button class="choice" data-level="${i}">${v}<span>${'•'.repeat(i+1)}</span></button>`).join('')+'<button class="quiet" data-menu="size">Назад</button></div>';app.innerHTML=`<section class="menu ${['difficulty','size'].includes(which)?'difficulty':''} ${which==='home'?'home-scene':''}"><header class="topbar">${brand()}${balance()}</header>${which==='home'?homeAtmosphere():''}${firstVisit?'<p class="notice" role="status">Молодец, что зашёл! Тебе в подарок 1 бакс.</p>':''}${storageError?`<p class="notice" role="alert">${storageError}</p>`:''}${content}</section>`;firstVisit=false;bindCommon();app.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{trialActive=false;mode=b.dataset.mode;menu(mode==='online'?'online':'size')});app.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{[fieldHeight,fieldWidth]=b.dataset.size==='small'?[10,14]:[28,20];if(mode==='room-create'){beginOnline('create',{size:[fieldHeight,fieldWidth]});}else if(mode==='trial'){progress.trial.size=[fieldHeight,fieldWidth];saveProgress();level=progress.trial.results.length;start('bot');}else if(mode==='bot')menu('difficulty');else start('local')});app.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=+b.dataset.level;start('bot')});}
function bindCommon(){app.querySelectorAll('[data-profile]').forEach(b=>b.onclick=showProfile);app.querySelectorAll('[data-account]').forEach(b=>b.onclick=showAccounts);app.querySelectorAll('[data-promo]').forEach(b=>b.onclick=showPromo);app.querySelectorAll('[data-nick]').forEach(b=>b.onclick=()=>showNick());app.querySelectorAll('[data-trial]').forEach(b=>b.onclick=beginTrial);app.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>menu(b.dataset.menu));app.querySelectorAll('[data-rules]').forEach(b=>b.onclick=()=>rules.showModal());}
function start(m){if(!progress.nick){showNick();return;}epoch++;matchStartedAt=Date.now();teleportSource=null;trialDamage=0;trialRecorded=false;trialStartedAt=null;trialElapsed=0;mode=m;if(mode==='bot'){botShopping(progress);saveProgress();}g=createGame(fieldHeight,fieldWidth);g.allowed=[progress.human.unlocked.slice(),(mode==='bot'?progress.bot:progress.human).unlocked.slice()];for(let p=0;p<2;p++)for(const t of Object.keys(g.stocks[p]))if(!g.allowed[p].includes(t))g.stocks[p][t]=0;matchId=globalThis.crypto?.randomUUID?.()??String(Date.now())+'-'+Math.random();actionId=0;screen='game';selected=null;notice=trialActive?'Испытание на звание · партия '+(level+1)+' из 5':'';render();if(mode==='bot'&&!tutorialActive)showOpponent({nick:'Бот · '+['Очень лёгкий','Лёгкий','Средний','Сложный','Безумно сложный'][level],rank:null,unlocked:g.allowed[1]});}
function boardCells(p,own){const energy=boostVisuals(g,p);const pending=new Set(g.pending.filter(v=>v.player===p).map(v=>v.index));return `${Array.from({length:g.boards[p].length},(_,n)=>{const i=own?n:(g.rows-1-Math.floor(n/g.width))*g.width+n%g.width,t=g.boards[p][i];return `<button class="cell ${own?'own':'enemy'} ${own&&i<g.width?'frontier':''} ${energy.cells.has(i)?'boost-path':''} ${energy.targets.has(i)?'boost-target':''} ${tutorialActive&&coachAdvice?.move?.index===i&&p===0?'coach-target':''} ${i>=(g.rows-1)*g.width?'home-row':''} ${(i+1)%g.width===0?'last-column':''} ${t?.spent?'spent':''} ${pending.has(i)?'pending':''}" data-side="${p}" data-index="${i}" data-symbol="${t?.type||'empty'}" aria-label="${name(p)}, ряд ${Math.floor(i/g.width)+1}, клетка ${i%g.width+1}${t?', '+(t.type==='king'?'Король':TYPES[t.type].name)+(t.spent?', выстрел использован':''):''}${energy.cells.has(i)?', проходит усиление':''}${energy.targets.has(i)?', получает усиление':''}" ${(!own||busy)?'tabindex="-1"':''}>${energy.cells.has(i)?lightning(own?energy.cells.get(i).dir:(4-energy.cells.get(i).dir+8)%8,!!t):''}${t?icon(t.type,own?t.dir:(4-(t.dir??0)+8)%8):''}</button>`;}).join('')}`;}
function playerHeader(p,own){return `<div class="arena-player ${own?'own':'enemy'}"><div class="board-head"><button class="player-name quiet" data-player-nick="${p}">${name(p)}</button><span class="health">${g.hp[p]} <small>/ ${g.maxHp[p]}</small></span></div><div class="hp-track"><span style="width:${Math.min(100,g.hp[p]/g.maxHp[p]*100)}%"></span></div></div>`;}
function arena(view){return `<section class="arena">${playerHeader(1-view,false)}<div class="board-scroll"><div class="board unified-board ${zoom?'zoom':''}" style="grid-template-columns:repeat(${g.width},1fr)" role="group" aria-label="Единое игровое поле с границей посередине">${boardCells(1-view,false)}${boardCells(view,true)}</div></div>${playerHeader(view,true)}</section>`;}
function render(){if(!g)return;coachAdvice=tutorialActive?tutorialAdvice(g):null;const view=mode==='online'?onlineMatch.seat:mode==='bot'?0:g.current;let hint=g.setup<2?`Выбери одну из ${g.width} клеток нижнего ряда для короны.`:selected?selected==='erase'?'Нажми на свой символ, чтобы удалить его.':selected==='teleport'&&teleportSource===null?'Выбери свой символ для переноса.':'Нажми на пустую клетку своей половины.':busy?'Смотри, как летит пуля.':'Выбери символ внизу и поставь его на поле.';if(mode==='bot'&&g.current===1)hint='Бот обдумывает ход…';app.innerHTML=`<div class="game"><header class="topbar game-header">${brand()}${balance()}<div class="top-actions"><button class="quiet" id="sound-toggle">Звук: ${soundEnabled()?'вкл':'выкл'}</button>${mode==='bot'&&(!trialActive||instantWinsLeft(progress)===Infinity)&&g.winner===null&&instantWinsLeft(progress)>0?`<button class="primary" id="instant-win" ${busy?'disabled':''}>Победить · ${instantWinsLeft(progress)===Infinity?'∞':instantWinsLeft(progress)}</button>`:''}<button class="quiet" id="zoom">${zoom?'Уменьшить':'Увеличить'}</button><button class="quiet" data-rules>Правила</button><button class="quiet" id="exit">Меню</button></div></header>${mode==='online'?'<div class="notice" id="online-banner"></div>':''}${trialActive?'<p class="trial-clock" data-trial-clock></p>':''}<div class="turnbar"><div><h1>${g.setup<2?'Расставляем королей':`Ходит ${name(g.current)}`}${g.extra?' · осталось действий: '+g.extra:''}</h1><div class="hint" aria-live="polite">${hint}</div></div><span class="turn-count">${g.setup<2?`${g.setup+1} / 2`:'Ход '+g.turn} · ${g.height} × ${g.width}</span></div>${notice?`<div class="notice" role="status">${notice}</div>`:''}${tutorialActive?coachPanel():''}${arena(view)}</div><footer class="shelf">${g.setup<2?'<div class="selection"><div><strong>Поставь своего короля</strong><p>Нижний ряд выделен цветом.</p></div>'+icon('king')+'</div>':selected?`<div class="selection"><div>${icon(selected)}</div><div><strong>${TYPES[selected].name}</strong><p>${selected==='erase'||selected==='teleport'&&teleportSource===null?'Выбери свой символ':'Выбери свободную клетку'}</p></div><button class="quiet" id="cancel">Отмена</button></div>`:`<div class="shelf-title"><span>Твои символы</span><span class="hint">${name(g.current)}${mode==='bot'&&g.current===1?' · '+progress.bot.balance+' баксов':''}</span></div><div class="pieces">${Object.entries(TYPES).filter(([t])=>g.allowed[view].includes(t)).map(([t,v])=>`<button class="piece ${tutorialActive&&coachAdvice?.move?.type===t?'coach-piece':''}" data-piece="${t}" ${busy||g.winner!==null||mode==='bot'&&g.current===1||mode==='online'&&g.current!==onlineMatch.seat||g.stocks[view][t]===0?'disabled':''} title="${descriptions[t]}">${icon(t)}<strong>${v.name}</strong><span class="stock">${g.stocks[view][t]??'∞'}</span></button>`).join('')}</div>`}</footer>`;updateTrialClock();bindCommon();app.querySelector('#sound-toggle').onclick=()=>{toggleSound();render();};app.querySelector('[data-coach-select]')?.addEventListener('click',selectCoachMove);app.querySelector('#instant-win')?.addEventListener('click',winByPromo);app.querySelector('#zoom').onclick=()=>{zoom=!zoom;render()};app.querySelector('#exit').onclick=()=>confirmExit();app.querySelector('#cancel')?.addEventListener('click',()=>{selected=null;teleportSource=null;render()});app.querySelectorAll('[data-piece]').forEach(b=>b.onclick=()=>{selected=b.dataset.piece;teleportSource=null;if(selected==='angry'){perform({type:'angry'});return;}notice='';render()});app.querySelectorAll('[data-player-nick]').forEach(b=>b.onclick=()=>mode==='online'?showNick(onlineMatch.state.players[+b.dataset.playerNick]):showNick(+b.dataset.playerNick===0?null:{nick:'Бот',rank:null}));app.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>cell(+b.dataset.side,+b.dataset.index));}
function cell(p,index){if(g&&!busy&&selected==='erase'&&p!==(mode==='online'?onlineMatch.seat:g.current)){notice='Чужую пулю и чужие символы удалить нельзя. Удаление действует только на свои фигуры.';render();return;}if(busy||!g||g.winner!==null||p!==g.current||mode==='bot'&&p===1||mode==='online'&&p!==onlineMatch.seat)return;if(g.setup<2){perform({type:'king',index});return;}if(!selected){notice='Сначала выбери символ внизу.';render();return;}if(selected==='teleport'&&teleportSource===null){if(!g.boards[p][index]||g.boards[p][index].type==='king'){notice='Выбери свой символ, кроме короля.';render();return;}teleportSource=index;render();return;}if(selected!=='erase'&&g.boards[p][index]){notice='Эта клетка занята.';render();return;}if(DIRECTED.includes(selected)||selected==='teleport'&&DIRECTED.includes(g.boards[p][teleportSource].type)){chosenCell=index;document.querySelector('#direction-title').textContent='Куда направить '+(BOOSTERS[selected]?'усиление?':'выстрел?');document.querySelectorAll('[data-dir]').forEach(b=>b.classList.toggle('coach-direction',tutorialActive&&coachAdvice?.move?.dir===+b.dataset.dir));dirs.showModal();}else perform({type:selected,index,source:teleportSource,side:p});}
async function perform(a){if(busy||!g)return;if(mode==='online')return performOnline(a);const token=epoch;let result;const old=g.current;try{result=action(g,a)}catch(e){notice=e.message;render();return;}recordTrial(result);if(g.winner!==null)recordLocalMatch();const paid=settle(progress,{id:matchId+':'+(++actionId),mode,events:result.events,winner:g.winner});saveProgress();selected=null;busy=true;notice=result.angry?`${name(old)} использовал символ «Злой». Два действия подряд!`:result.free?(g.pending.some(v=>v.player!==old)?'Своя фигура удалена. Вражеский выстрел остаётся: он полетит после твоего хода.':'Символ удалён. Твой ход продолжается.'):result.cancelled?'Король получил урон. Ответная атака отменена — выбери другой ход.':'';if(paid.length){const ours=paid.filter(x=>x.who==='human').reduce((n,x)=>n+x.amount,0),theirs=paid.filter(x=>x.who==='bot').reduce((n,x)=>n+x.amount,0);notice+=(notice?' ':'')+(ours?'Задание выполнено! +'+ours+' баксов. ':'')+(theirs?'Бот заработал '+theirs+' баксов.':'');}if(storageError)notice+=' '+storageError;render();await animateShots(app,result.events,()=>epoch===token);if(epoch!==token)return;busy=false;render();if(g.winner!==null){if(tutorialActive){finishTutorial();return;}if(trialActive){trialFinish();return;}overlay(`${name(g.winner)} победил!`,'Король соперника повержен. '+(notice||'Ещё одну партию?'),'Сыграть ещё раз',()=>start(mode));return;}if(mode==='bot'&&g.current===1){runBot();return;}if(mode==='local'&&old!==g.current){overlay(`Передай устройство`,`${name(g.current)}, теперь твоя очередь.`,'Я готов',()=>render());}}
function runBot(){const token=epoch;busy=true;render();setTimeout(()=>{if(epoch!==token||!g)return;let a;try{a=botAction(g,level)}catch{notice='Бот не смог выбрать ход. Попробуй начать новую партию.';busy=false;render();return;}busy=false;perform(a)},550);}
function overlay(title,subtitle,label,callback){const el=document.createElement('div');el.className='overlay';el.innerHTML=`<div class="overlay-card"><div class="big-crown">${icon('king')}</div><h2>${title}</h2><p>${subtitle}</p><button class="primary">${label}</button>${g?.winner!==null?'<button class="quiet" data-finish-menu>В меню и рынок</button>':''}</div>`;app.append(el);el.querySelector('[data-finish-menu]')?.addEventListener('click',()=>mode==='online'?leaveOnline():menu());const b=el.querySelector('button');b.onclick=()=>{el.remove();callback()};b.focus();}
function confirmExit(){if(mode==='online'){leaveOnline();return;}const el=document.createElement('div');el.className='overlay';el.innerHTML='<div class="overlay-card"><h2>Выйти в меню?</h2><p>Текущая партия закончится.</p><button class="primary" id="yes-exit">Выйти</button><button class="quiet" id="no-exit">Продолжить игру</button></div>';app.append(el);el.querySelector('#yes-exit').onclick=()=>{if(g?.winner===null&&g.setup===2)recordLocalMatch('abandoned');if(tutorialActive){finishTutorial(true);return;}menu();};el.querySelector('#no-exit').onclick=()=>el.remove();}
document.querySelector('#direction-grid').innerHTML=[7,0,1,6,null,2,5,4,3].map(d=>d===null?'<span class="direction-center">•</span>':`<button data-dir="${d}" aria-label="${['Вверх','Вверх вправо','Вправо','Вниз вправо','Вниз','Вниз влево','Влево','Вверх влево'][d]}">${arrows[d]}</button>`).join('');
document.querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>{dirs.close();perform({type:selected,index:chosenCell,dir:+b.dataset.dir,source:teleportSource})});document.querySelector('#cancel-direction').onclick=()=>dirs.close();document.querySelector('#close-rules').onclick=()=>rules.close();document.querySelector('#rule-symbols').innerHTML=Object.entries(TYPES).map(([t,v])=>`<div class="rule-row">${icon(t)}<div><strong>${v.name}</strong><p>${descriptions[t]}</p></div></div>`).join('');
app.innerHTML='<div class="splash"><h1>Символы</h1></div>';setTimeout(()=>{if(screen==='splash'){menu();if(!progress.nick)showNick();else maybeStartTutorial();}},4400);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_symbols_game',description:'Read the current Symbols game state without making a move.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>g?structuredClone({height:g.height,width:g.width,current:g.current,hp:g.hp,maxHp:g.maxHp,boards:g.boards,stocks:g.stocks,pending:g.pending,winner:g.winner}):{screen}})).catch(()=>{});}catch{}}

const promoDialog=document.createElement('dialog');promoDialog.id='promo-dialog';document.body.append(promoDialog);
function showPromo(){promoDialog.innerHTML=`<h2>Промокоды</h2><form><label for="promo-input">Введи промокод</label><input id="promo-input" maxlength="80" autocomplete="off" placeholder="Твой промокод" required><p class="hint">M4FX можно активировать до пяти раз. Остальные коды — один раз.</p><p data-promo-result role="status" aria-live="polite"></p><div class="dialog-actions"><button class="primary" type="submit">Активировать</button><button class="quiet" type="button" data-close>Закрыть</button></div></form>`;promoDialog.querySelector('[data-close]').onclick=()=>promoDialog.close();promoDialog.querySelector('form').onsubmit=e=>{e.preventDefault();const result=promoDialog.querySelector('[data-promo-result]');try{if(!storageReady)throw Error('Не удалось открыть сохранение. Проверь доступ браузера к данным сайта.');const next=structuredClone(progress);const amount=redeemPromo(next,promoDialog.querySelector('input').value);accountStorage.setItem(STORAGE_KEY,JSON.stringify(next));progress=next;menu('home');result.textContent=amount?`Промокод активирован! +${amount} баксов на твой баланс.`:`Промокод активирован! Побед доступно: ${instantWinsLeft(progress)===Infinity?'без ограничений':instantWinsLeft(progress)}. Только обычные партии с ботом, без наград и влияния на звание.`;promoDialog.querySelector('input').value='';}catch(error){result.textContent=error.message;}};promoDialog.showModal();promoDialog.querySelector('input').focus();}

function winByPromo(){if(busy||opponentDialog.open)return;try{if(!storageReady)throw Error('Не удалось открыть сохранение.');const next=structuredClone(progress),game=structuredClone(g);useInstantWin(next,game,mode,trialActive);accountStorage.setItem(STORAGE_KEY,JSON.stringify(next));progress=next;g=game;recordLocalMatch('win','promo');epoch++;selected=null;busy=false;dirs.close();opponentDialog.close();if(tutorialActive){finishTutorial();return;}if(trialActive){recordTrial({events:[]});render();trialFinish();return;}notice='Победа по промокоду. Баксы, серия побед и звание не изменились.';render();overlay('Ты победил!',`Победа по промокоду, без наград. Осталось использований: ${instantWinsLeft(progress)===Infinity?'без ограничений':instantWinsLeft(progress)}.`,'Сыграть ещё раз',()=>start('bot'));}catch(e){notice=e.message;render();}}

function updateTrialClock(){const el=app.querySelector('[data-trial-clock]');if(!el)return;if(g?.winner===null)trialElapsed=trialStartedAt===null?0:performance.now()-trialStartedAt;el.textContent=`Время: ${(trialElapsed/1000).toFixed(1)} с`+((progress.rank?.index??0)>=15?' · Для повышения: каждая из 5 побед быстрее 30 секунд, без урона.':' · Пять побед без урона дают Легенду.');}
setInterval(updateTrialClock,100);

const accountDialog=document.createElement('dialog');accountDialog.id='account-dialog';document.body.append(accountDialog);
function showAccounts(){if(!accountManager){notice='Не удалось открыть список аккаунтов.';return;}accountDialog.innerHTML=`<h2>Аккаунт</h2><p class="hint">Аккаунты сохраняются в этом браузере на этом устройстве.</p><div class="account-list">${accountManager.list().map(a=>`<article class="account-item"><strong>${escapeHtml(a.name)}</strong><span>${rankBadge(a.rank)} · ${a.balance} баксов</span><button class="${a.id===accountManager.active?'quiet':'choice'}" data-switch-account="${a.id}" ${a.id===accountManager.active?'disabled':''}>${a.id===accountManager.active?'Текущий аккаунт':'Войти'}</button></article>`).join('')}</div><p id="account-error" role="alert"></p><button class="primary" data-new-account>Создать новый аккаунт</button><button class="quiet" data-close>Закрыть</button>`;accountDialog.querySelector('[data-close]').onclick=()=>accountDialog.close();const change=id=>{try{if(onlineBusy||onlineMatch&&onlineMatch.status!=='done')throw Error('Сначала заверши онлайн-дуэль или выйди из поиска.');if(!saveProgress())throw Error(storageError);accountManager.select(id||accountManager.create());location.reload();}catch(e){accountDialog.querySelector('#account-error').textContent=e.message;}};accountDialog.querySelector('[data-new-account]').onclick=()=>change(null);accountDialog.querySelectorAll('[data-switch-account]').forEach(b=>b.onclick=()=>change(b.dataset.switchAccount));accountDialog.showModal();}

const profileDialog=document.createElement('dialog');document.body.append(profileDialog);
function showProfile(){profileDialog.innerHTML=`<h2>${escapeHtml(progress.nick||'Твой профиль')}</h2><div class="profile-emblem">${rankBadge(progress.rank,'large')}</div><p>${progress.human.balance} баксов</p>${historyPanel()}<button class="primary" data-recovery>Восстановить аккаунт</button><button class="quiet" data-close>Закрыть</button>`;profileDialog.querySelector('[data-close]').onclick=()=>profileDialog.close();profileDialog.querySelector('[data-recovery]').onclick=showRecovery;profileDialog.showModal();}

function showRecovery(){profileDialog.innerHTML=`<h2>Восстановить аккаунт</h2><p>Сохрани свой код, чтобы войти на другом устройстве. Не показывай его другим людям.</p><button class="primary" data-get-code>Показать мой код</button><p class="recovery-code" data-code></p><p class="hint">Код сохраняет текущий прогресс на сервере. После игры открой это окно и нажми «Показать мой код», чтобы обновить сохранение перед переносом. Вход на новом устройстве отключит старую онлайн-сессию.</p><form><label for="recovery-input">Код с другого устройства</label><input id="recovery-input" inputmode="numeric" pattern="[0-9]{9}" maxlength="9" required autocomplete="off"><button class="primary">Войти по коду</button></form><p data-recovery-status role="status"></p><button class="quiet" data-close>Закрыть</button>`;const status=profileDialog.querySelector('[data-recovery-status]');profileDialog.querySelector('[data-close]').onclick=()=>profileDialog.close();profileDialog.querySelector('[data-get-code]').onclick=async e=>{e.target.disabled=true;try{await ensureSession();const r=await api('recovery-code',{progress,nick:progress.nick,code:accountStorage.getItem('symbols-recovery-code')});accountStorage.setItem('symbols-recovery-code',r.code);profileDialog.querySelector('[data-code]').textContent=r.code;status.textContent='Прогресс сохранён. Запомни или запиши код.';}catch(err){status.textContent=err.message;}finally{e.target.disabled=false;}};profileDialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{if(g||onlineBusy||onlineMatch&&onlineMatch.status!=='done')throw Error('Сначала выйди в главное меню и заверши онлайн-дуэль.');if(!saveProgress())throw Error(storageError);const code=profileDialog.querySelector('input').value;const r=await api('recover',{code});const id=accountManager.restore(r,code);accountManager.select(id);location.reload();}catch(err){status.textContent=err.message;button.disabled=false;}};if(progress.nick)profileDialog.querySelector('[data-get-code]').click();}

let tutorialActive=false,coachAdvice=null,matchStartedAt=Date.now();
const learningDialog=document.createElement('dialog');learningDialog.id='learning-dialog';document.body.append(learningDialog);
function maybeStartTutorial(){if(!progress.nick||!['new','playing'].includes(progress.tutorial?.status)||g)return;learningDialog.innerHTML='<h2>Твоя первая партия</h2><div class="learning-basics"><p>Поставь короля в нижний ряд и защищай его.</p><p>Стрелочка стреляет туда, куда направлена; смайлик останавливает слабую пулю.</p><p>За ход ставь один символ: пуля летит после ответа соперника.</p><p>Чтобы победить, снизь жизни чужого короля до нуля.</p></div><button class="primary" data-learn-start>Начать · очень лёгкий бот</button><button class="quiet" data-learn-later>Не сейчас</button>';learningDialog.querySelector('[data-learn-start]').onclick=()=>{learningDialog.close();progress.tutorial={status:'playing'};saveProgress();trialActive=false;tutorialActive=true;level=0;fieldHeight=10;fieldWidth=14;start('bot');};learningDialog.querySelector('[data-learn-later]').onclick=()=>{progress.tutorial={status:'skipped'};saveProgress();learningDialog.close();};learningDialog.showModal();}
function coachPanel(){if(busy||g.current!==0)return '<aside class="coach-panel"><strong>Смотри на ход бота</strong><p>После его ответа снова будет твоя очередь.</p></aside>';return `<aside class="coach-panel"><strong>Подсказка для тебя</strong><p>${escapeHtml(coachAdvice?.text||'Выбери символ и клетку. Защищай короля.')}</p>${coachAdvice?.move&&g.setup===2?'<button class="quiet" data-coach-select>Выбрать предложенный символ</button>':''}</aside>`;}
function selectCoachMove(){if(!coachAdvice?.move)return;selected=coachAdvice.move.type;notice='Подсвеченная клетка — предложенный ход. Можно выбрать свой.';render();}
function finishTutorial(abandoned=false){progress.tutorial={status:'done'};saveProgress();tutorialActive=false;epoch++;busy=false;learningDialog.innerHTML=`<h2>${abandoned?'Ты попробовал игру!':g?.winner===0?'Первая победа!':'Первая партия завершена'}</h2><p>Если что-то осталось непонятным, открой правила игры. Их всегда можно найти в меню.</p><button class="primary" data-learn-rules>Посмотреть правила</button><button class="quiet" data-learn-home>В главное меню</button>`;learningDialog.querySelector('[data-learn-rules]').onclick=()=>{learningDialog.close();menu();rules.showModal();};learningDialog.querySelector('[data-learn-home]').onclick=()=>{learningDialog.close();menu();};render();learningDialog.showModal();}
function recordLocalMatch(outcome=null,method='normal'){if(!g||mode==='online')return;recordMatch(progress,{id:matchId,at:Date.now(),mode:trialActive?'trial':mode,level:mode==='bot'?level:null,opponent:mode==='bot'?'Бот':'Игрок 2',outcome:outcome||(g.winner===0?'win':'loss'),method,tutorial:tutorialActive,turns:g.turn,hp:g.hp[0],durationMs:Math.max(0,Date.now()-matchStartedAt)});saveProgress();}
function historyPanel(){const matches=(progress.history||[]).slice(0,100),wins=matches.filter(m=>m.outcome==='win').length,losses=matches.filter(m=>m.outcome==='loss').length;return `<section class="match-history"><h3>История матчей</h3><p class="history-summary">${wins} побед · ${losses} поражений · последние ${matches.length} партий</p>${matches.length?`<ol>${matches.map(m=>`<li><div><strong class="result-${m.outcome==='win'?'win':m.outcome==='loss'?'loss':'other'}">${m.outcome==='win'?'Победа':m.outcome==='loss'?'Поражение':'Выход из партии'}</strong><span>${escapeHtml(m.mode==='online'?m.opponent:m.mode==='local'?'На одном устройстве':'Бот · '+(LEVEL_NAMES[m.level]||'Сложность не указана'))}</span>${m.mode==='trial'?'<small>Испытание на звание</small>':''}${m.method==='promo'?'<small>Победа по промокоду</small>':''}${m.tutorial?'<small>Первая партия с подсказками</small>':''}</div><time>${new Date(m.at).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time></li>`).join('')}</ol>`:'<p>Здесь появятся результаты новых партий. История началась с этого обновления.</p>'}</section>`;}
function homeAtmosphere(){return `<div class="home-effects" aria-hidden="true">${Array.from({length:9},(_,i)=>`<span class="home-fly home-fly-${i%3}" style="--lane:${9+i*10}%;--delay:-${i*1.7}s;--speed:${7+i%4}s">${i%3===0?icon('arrow',2):i%3===1?'<svg viewBox="0 0 40 40"><path d="m24 2-17 22h13l-4 14 17-23H20z" fill="#70dfff"/></svg>':'<i class="home-shell"></i>'}</span>`).join('')}</div>`;}
